UPDATE tools SET faq = $x$[{"a": "OpenAI Codex is OpenAI's coding agent. It takes tasks such as fixing bugs, refactoring, adding features and writing tests, works through your repository and returns changes for review. It runs in the ChatGPT apps, the Codex CLI, an IDE extension and Codex cloud, and can also review pull requests automatically.", "q": "What is OpenAI Codex?"}, {"a": "Partly. The ChatGPT Free plan and Go ($8 a month) include lightweight Codex use in the desktop app with the GPT-6 Luna model, subject to rollout. Full Codex on the web, CLI, IDE extension and iOS starts with ChatGPT Plus at $20 a month. Pro costs $100, $200 or $500 a month, and Business is $20 per user per month billed annually or $25 billed monthly.", "q": "Is OpenAI Codex free?"}, {"a": "As of October 2026, OpenAI lists GPT-6.1 Sol, GPT-6 Sol, GPT-6 Luna and GPT-6 Astra for Codex. Plus users get GPT-6.1 Sol and GPT-6 Luna. GPT-5.5 was retired from Codex for ChatGPT sign-in on October 14, 2026.", "q": "Which models does Codex use?"}, {"a": "On Plus and Business, Codex usage is measured per five-hour window. OpenAI estimates about 15 to 160 local messages per five hours with GPT-6.1 Sol and 350 to 3,000 with GPT-6 Luna. Pro currently has no five-hour limit, and Plus, Pro and Business users can buy extra credits.", "q": "What are the Codex usage limits?"}]$x$::jsonb
 WHERE slug = 'openai-codex' AND lang = 'en';

