UPDATE tools SET faq = $x$[{"a": "OpenAI Codex est l'agent de codage d'OpenAI. Il prend en charge des tâches comme la correction de bugs, la refactorisation, l'ajout de fonctionnalités et l'écriture de tests, travaille sur votre dépôt et renvoie des modifications pour révision. Il fonctionne dans les applications ChatGPT, le Codex CLI, une extension IDE et Codex cloud, et peut aussi réviser automatiquement les pull requests.", "q": "Qu'est-ce qu'OpenAI Codex ?"}, {"a": "En partie. Le plan ChatGPT Free et Go (8 $ par mois) incluent une utilisation légère de Codex dans l'application de bureau avec le modèle GPT-6 Luna, sous réserve du déploiement. Codex complet sur le web, le CLI, l'extension IDE et iOS commence avec ChatGPT Plus à 20 $ par mois. Pro coûte 100 $, 200 $ ou 500 $ par mois, et Business coûte 20 $ par utilisateur et par mois facturé annuellement ou 25 $ facturé mensuellement.", "q": "OpenAI Codex est-il gratuit ?"}, {"a": "En octobre 2026, OpenAI répertorie GPT-6.1 Sol, GPT-6 Sol, GPT-6 Luna et GPT-6 Astra pour Codex. Les utilisateurs Plus obtiennent GPT-6.1 Sol et GPT-6 Luna. GPT-5.5 a été retiré de Codex pour la connexion ChatGPT le 14 octobre 2026.", "q": "Quels modèles Codex utilise-t-il ?"}, {"a": "Sur Plus et Business, l'utilisation de Codex est mesurée par fenêtre de cinq heures. OpenAI estime environ 15 à 160 messages locaux par cinq heures avec GPT-6.1 Sol et 350 à 3 000 avec GPT-6 Luna. Pro n'a actuellement aucune limite de cinq heures, et les utilisateurs Plus, Pro et Business peuvent acheter des crédits supplémentaires.", "q": "Quelles sont les limites d'utilisation de Codex ?"}]$x$::jsonb
 WHERE slug = 'openai-codex' AND lang = 'fr';

