UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Higgsfield ?", "a": "Higgsfield est une plateforme créative IA pour la vidéo, les images et l'audio. Elle combine des modèles tiers comme Kling, Seedance, Google Veo et Nano Banana avec ses propres outils pour la publicité, les clips sociaux, le placement de produits et les influenceurs IA, et est utilisée par des créateurs, des marques et des agences."}, {"q": "Combien coûte Higgsfield ?", "a": "Il existe un plan Free avec usage limité. Starter coûte 19 $ par mois, au même prix facturé mensuellement ou annuellement, avec 270 crédits. Plus coûte 47 $ par mois facturé annuellement ou 59 $ facturé mensuellement avec 1 200 crédits. Ultra coûte 99 $ par mois facturé annuellement ou 129 $ facturé mensuellement avec 3 000 crédits. Les plans Team commencent à 65 $ par poste et par mois. Les prix sont hors TVA."}, {"q": "Higgsfield est-il vraiment illimité ?", "a": "Seulement en partie. Plus et Ultra incluent des fenêtres illimitées de 7 jours sur certains modèles sélectionnés comme Kling et Nano Banana. Celles-ci s'appliquent uniquement sur higgsfield.ai, pas via MCP, CLI, Canvas ou Supercomputer, et la vitesse peut être réduite en cas de forte affluence. Tout le reste fonctionne avec des crédits."}, {"q": "Quelle est la taille de Higgsfield ?", "a": "En septembre 2026, Higgsfield a annoncé avoir dépassé un taux de revenu annualisé de 1 milliard de dollars, calculé comme quatre semaines de revenu multipliées par 13, avec plus de 32 millions d'utilisateurs et près d'un million d'abonnés payants. Ce sont des chiffres propres à l'entreprise, non audités."}]$x$::jsonb
