 WHERE slug = 'granola' AND lang = 'en';

UPDATE tools SET faq = $x$[{"a": "Granola is an AI notepad for meetings. It transcribes audio from your computer or phone without a bot joining the call and turns your rough notes plus the transcript into structured notes, action items and follow-ups. It works with Zoom, Google Meet, Teams, Slack huddles and in-person meetings.", "q": "What is Granola?"}, {"a": "Yes, the Basic plan is free and includes AI meeting notes, chat, shared folders and templates, but you can only see the last 30 days of meeting history. Business costs $14 per user per month for unlimited history, briefs, follow-up emails, integrations, MCP and API access. Enterprise costs $35 per user per month.", "q": "Is Granola free?"}, {"a": "No. Granola records audio from your own device, so no bot appears in the call. That also means other participants are not automatically notified, so you should tell them you are taking AI notes. An organization-wide notification is available as a pilot on Enterprise.", "q": "Does Granola use a meeting bot?"}, {"a": "Granola has apps for macOS, Windows, iOS and Android, plus an Apple Watch app launched in July 2026. It also connects to AI tools such as Claude, ChatGPT and Cursor through its MCP connector.", "q": "Which platforms does Granola support?"}]$x$::jsonb
 WHERE slug = 'granola' AND lang = 'en';

