UPDATE tools SET faq = $x$[{"a": "Granola es un bloc de notas con IA para reuniones. Transcribe el audio de tu computadora o teléfono sin que un bot se una a la llamada y convierte tus notas rápidas junto con la transcripción en notas estructuradas, tareas pendientes y seguimientos. Funciona con Zoom, Google Meet, Teams, Slack huddles y reuniones presenciales.", "q": "¿Qué es Granola?"}, {"a": "Sí, el plan Basic es gratuito e incluye notas de reuniones con IA, chat, carpetas compartidas y plantillas, pero solo puedes ver el historial de reuniones de los últimos 30 días. Business cuesta 14 dólares por usuario al mes por historial ilimitado, resúmenes, correos de seguimiento, integraciones, acceso a MCP y API. Enterprise cuesta 35 dólares por usuario al mes.", "q": "¿Es gratis Granola?"}, {"a": "No. Granola graba el audio desde tu propio dispositivo, por lo que ningún bot aparece en la llamada. Eso también significa que los demás participantes no son notificados automáticamente, así que debes avisarles de que estás tomando notas con IA. Una notificación a nivel de toda la organización está disponible como función piloto en Enterprise.", "q": "¿Granola usa un bot de reuniones?"}, {"a": "Granola tiene aplicaciones para macOS, Windows, iOS y Android, además de una aplicación para Apple Watch lanzada en julio de 2026. También se conecta con herramientas de IA como Claude, ChatGPT y Cursor a través de su conector MCP.", "q": "¿Qué plataformas admite Granola?"}]$x$::jsonb
