UPDATE tools SET faq = $x$[{"a": "Granola est un bloc-notes IA pour les réunions. Il transcrit l'audio depuis votre ordinateur ou téléphone sans qu'un bot ne rejoigne l'appel, et transforme vos notes brutes et la transcription en notes structurées, actions à mener et suivis. Il fonctionne avec Zoom, Google Meet, Teams, les huddles Slack et les réunions en personne.", "q": "Qu'est-ce que Granola ?"}, {"a": "Oui, le forfait Basic est gratuit et inclut les notes de réunion IA, le chat, les dossiers partagés et les modèles, mais vous ne pouvez voir que les 30 derniers jours d'historique de réunions. Business coûte 14 $ par utilisateur et par mois pour un historique illimité, les briefs, les e-mails de suivi, les intégrations, l'accès MCP et API. Enterprise coûte 35 $ par utilisateur et par mois.", "q": "Granola est-il gratuit ?"}, {"a": "Non. Granola enregistre l'audio depuis votre propre appareil, donc aucun bot n'apparaît dans l'appel. Cela signifie aussi que les autres participants ne sont pas automatiquement informés, vous devez donc leur indiquer que vous prenez des notes avec l'IA. Une notification à l'échelle de l'organisation est disponible en version pilote sur Enterprise.", "q": "Granola utilise-t-il un bot de réunion ?"}, {"a": "Granola propose des applications pour macOS, Windows, iOS et Android, ainsi qu'une application Apple Watch lancée en juillet 2026. Il se connecte aussi à des outils IA comme Claude, ChatGPT et Cursor via son connecteur MCP.", "q": "Quelles plateformes Granola prend-il en charge ?"}]$x$::jsonb
