UPDATE tools SET faq = $x$[{"a": "Granola é um bloco de notas com IA para reuniões. Ele transcreve o áudio do seu computador ou telefone sem que um bot entre na chamada e transforma suas anotações rápidas, somadas à transcrição, em notas estruturadas, itens de ação e acompanhamentos. Funciona com Zoom, Google Meet, Teams, Slack huddles e reuniões presenciais.", "q": "O que é o Granola?"}, {"a": "Sim, o plano Basic é gratuito e inclui notas de reunião com IA, chat, pastas compartilhadas e modelos, mas você só pode ver os últimos 30 dias de histórico de reuniões. O Business custa $14 por usuário por mês para histórico ilimitado, briefings, e-mails de acompanhamento, integrações, acesso a MCP e API. O Enterprise custa $35 por usuário por mês.", "q": "O Granola é gratuito?"}, {"a": "Não. O Granola grava o áudio a partir do seu próprio dispositivo, então nenhum bot aparece na chamada. Isso também significa que os outros participantes não são notificados automaticamente, então você deve avisá-los de que está fazendo anotações com IA. Uma notificação em toda a organização está disponível como recurso piloto no Enterprise.", "q": "O Granola usa um bot de reunião?"}, {"a": "O Granola tem aplicativos para macOS, Windows, iOS e Android, além de um aplicativo para Apple Watch lançado em julho de 2026. Ele também se conecta a ferramentas de IA como Claude, ChatGPT e Cursor por meio do seu conector MCP.", "q": "Quais plataformas o Granola suporta?"}]$x$::jsonb
 WHERE slug = 'granola' AND lang = 'pt';

