UPDATE tools SET faq = $x$[{"q": "¿Para qué se usa Photoroom?", "a": "Photoroom se usa para crear fotos de productos para tiendas en línea y marketplaces. Elimina fondos, añade sombras, coloca productos en escenas generadas por IA, viste a modelos de moda con IA, crea vídeos cortos de producto y edita por lotes catálogos completos."}, {"q": "¿Es gratis Photoroom?", "a": "Existe un plan Free con funciones limitadas y límites más bajos de créditos y exportaciones, solo para uso personal, no comercial, y sin acceso a la API. En EE. UU., Pro cuesta 12,99 $ al mes o 89,99 $ al año, Max 34,99 $ al mes o 249,99 $ al año, y Ultra 99 $ al mes o 990 $ al año. Los planes anuales Pro y Max incluyen una prueba gratuita de 7 días."}, {"q": "¿Qué son los créditos de IA de Photoroom?", "a": "Los créditos de IA pagan las herramientas más exigentes, como el Video Generator, AI Fashion Models, AI Backgrounds Studio y Edit with AI. Pro incluye 8.000 créditos al mes, Max 25.000 y Ultra 75.000. Las herramientas principales, como el Background Remover y Retouch, no consumen créditos en los planes de pago."}, {"q": "¿Tiene Photoroom una API?", "a": "Sí. Photoroom ofrece una API REST y un servidor MCP para herramientas como Claude. Cada plan de pago incluye una billetera de créditos de API y MCP por el valor del plan, y el uso de la API no cuenta para el límite de exportaciones. El plan Free no tiene acceso a la API."}]$x$::jsonb
