UPDATE tools SET faq = $x$[{"q": "Wofür wird Photoroom verwendet?", "a": "Photoroom wird verwendet, um Produktfotos für Online-Shops und Marketplaces zu erstellen. Es entfernt Hintergründe, fügt Schatten hinzu, platziert Produkte in KI-generierten Szenen, zieht Kleidung auf KI-Modemodelle an, erstellt kurze Produktvideos und bearbeitet ganze Kataloge stapelweise."}, {"q": "Ist Photoroom kostenlos?", "a": "Es gibt einen kostenlosen Plan mit eingeschränkten Funktionen und niedrigeren Credit- und Export-Limits, der nur für den persönlichen, nicht-kommerziellen Gebrauch bestimmt ist und keinen API-Zugang bietet. In den USA kostet Pro 12,99 $ pro Monat oder 89,99 $ pro Jahr, Max 34,99 $ pro Monat oder 249,99 $ pro Jahr und Ultra 99 $ pro Monat oder 990 $ pro Jahr. Die Jahrespläne Pro und Max beinhalten eine 7-tägige kostenlose Testphase."}, {"q": "Was sind Photoroom-KI-Credits?", "a": "KI-Credits bezahlen für die aufwändigeren Werkzeuge wie den Video Generator, AI Fashion Models, AI Backgrounds Studio und Edit with AI. Pro enthält 8.000 Credits pro Monat, Max 25.000 und Ultra 75.000. Kernwerkzeuge wie der Background Remover und Retouch verbrauchen bei kostenpflichtigen Plänen keine Credits."}, {"q": "Verfügt Photoroom über eine API?", "a": "Ja. Photoroom bietet eine REST-API und einen MCP-Server für Tools wie Claude. Jeder kostenpflichtige Plan enthält ein Guthaben an API- und MCP-Credits im Wert des Plan-Preises, und die API-Nutzung zählt nicht zum Export-Kontingent. Der kostenlose Plan bietet keinen API-Zugang."}]$x$::jsonb
 WHERE slug = 'photoroom' AND lang = 'de';

