UPDATE tools SET faq = $x$[{"q": "À quoi sert Photoroom ?", "a": "Photoroom sert à créer des photos de produits pour les boutiques en ligne et les places de marché. Il supprime les arrière-plans, ajoute des ombres, place les produits dans des décors générés par IA, habille des mannequins de mode IA, crée de courtes vidéos de produits et édite par lots des catalogues entiers."}, {"q": "Photoroom est-il gratuit ?", "a": "Il existe un plan Free avec des fonctionnalités limitées et des limites de crédits et d'exports plus basses, réservé à un usage personnel, non commercial, et sans accès API. Aux États-Unis, Pro coûte 12,99 $ par mois ou 89,99 $ par an, Max 34,99 $ par mois ou 249,99 $ par an, et Ultra 99 $ par mois ou 990 $ par an. Les plans annuels Pro et Max incluent un essai gratuit de 7 jours."}, {"q": "Que sont les crédits IA de Photoroom ?", "a": "Les crédits IA servent à payer les outils les plus gourmands, comme le Video Generator, AI Fashion Models, AI Backgrounds Studio et Edit with AI. Pro inclut 8 000 crédits par mois, Max 25 000 et Ultra 75 000. Les outils essentiels comme le Background Remover et Retouch n'utilisent pas de crédits sur les plans payants."}, {"q": "Photoroom dispose-t-il d'une API ?", "a": "Oui. Photoroom propose une API REST et un serveur MCP pour des outils comme Claude. Chaque plan payant inclut un portefeuille de crédits API et MCP d'une valeur équivalente au prix du plan, et l'utilisation de l'API ne compte pas dans votre quota d'exports. Le plan Free n'offre pas d'accès API."}]$x$::jsonb
