 WHERE slug = 'quizlet' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Quizlet?", "a": "Quizlet is a study platform for students and teachers. It turns your notes, documents and recorded lectures into flashcards, study guides, practice tests and games, and offers adaptive Learn mode, spaced repetition and expert textbook solutions."}, {"q": "Is Quizlet free?", "a": "Yes, Quizlet has a free plan, and it is free for teachers. Quizlet Plus adds 3 practice tests, 3 Q&A or textbook solutions and 20 Learn rounds a month with no ads, and Plus Unlimited removes those caps. Pricing varies by country and whether you choose monthly or annual billing."}, {"q": "What AI features does Quizlet have?", "a": "Quizlet can explain study material and generate practice materials from it, turn recorded lectures into study guides and flashcards, convert notes into conversational podcasts, and schedule reviews with spaced repetition. It also has an app inside ChatGPT for creating flashcard sets."}, {"q": "Does Quizlet Plus have a free trial?", "a": "Yes, annual Quizlet Plus plans include a 7-day free trial, after which you are billed for the year unless you cancel. Monthly plans are not eligible for the trial."}]$x$::jsonb
 WHERE slug = 'quizlet' AND lang = 'en';

