UPDATE tools SET faq = $x$[{"q": "¿Qué es Quizlet?", "a": "Quizlet es una plataforma de estudio para estudiantes y profesores. Convierte tus apuntes, documentos y clases grabadas en flashcards, guías de estudio, exámenes de práctica y juegos, y ofrece el modo adaptativo Learn, repetición espaciada y soluciones expertas de libros de texto."}, {"q": "¿Es gratis Quizlet?", "a": "Sí, Quizlet tiene un plan gratuito, y es gratis para profesores. Quizlet Plus añade 3 exámenes de práctica, 3 preguntas y respuestas o soluciones de libros de texto y 20 rondas Learn al mes sin anuncios, y Plus Unlimited elimina esos límites. Los precios varían según el país y si eliges facturación mensual o anual."}, {"q": "¿Qué funciones de IA tiene Quizlet?", "a": "Quizlet puede explicar el material de estudio y generar materiales de práctica a partir de él, convertir clases grabadas en guías de estudio y flashcards, convertir apuntes en podcasts conversacionales y programar repasos con repetición espaciada. También tiene una app dentro de ChatGPT para crear conjuntos de flashcards."}, {"q": "¿Tiene Quizlet Plus una prueba gratuita?", "a": "Sí, los planes anuales de Quizlet Plus incluyen una prueba gratuita de 7 días, después de la cual se te factura por el año a menos que canceles. Los planes mensuales no son elegibles para la prueba."}]$x$::jsonb
