UPDATE tools SET faq = $x$[{"q": "Was ist Quizlet?", "a": "Quizlet ist eine Lernplattform für Schüler, Studierende und Lehrkräfte. Sie verwandelt Notizen, Dokumente und aufgezeichnete Vorlesungen in Karteikarten, Lernleitfäden, Übungstests und Spiele und bietet einen adaptiven Learn-Modus, verteiltes Wiederholen und von Experten erstellte Lehrbuchlösungen."}, {"q": "Ist Quizlet kostenlos?", "a": "Ja, Quizlet bietet einen kostenlosen Plan und ist für Lehrkräfte kostenlos. Quizlet Plus bietet zusätzlich 3 Übungstests, 3 Fragen-Antworten oder Lehrbuchlösungen und 20 Learn-Runden pro Monat ohne Werbung, und Plus Unlimited entfernt diese Begrenzungen. Die Preise variieren je nach Land und danach, ob man sich für monatliche oder jährliche Abrechnung entscheidet."}, {"q": "Welche KI-Funktionen bietet Quizlet?", "a": "Quizlet kann Lernmaterial erklären und daraus Übungsmaterial generieren, aufgezeichnete Vorlesungen in Lernleitfäden und Karteikarten verwandeln, Notizen in gesprochene Podcasts umwandeln und Wiederholungen mit verteiltem Wiederholen planen. Zudem gibt es eine App innerhalb von ChatGPT zum Erstellen von Karteikartensets."}, {"q": "Hat Quizlet Plus eine kostenlose Testphase?", "a": "Ja, jährliche Quizlet-Plus-Pläne beinhalten eine 7-tägige kostenlose Testphase, danach wird für das Jahr abgerechnet, sofern nicht gekündigt wird. Monatspläne haben keinen Anspruch auf die Testphase."}]$x$::jsonb
 WHERE slug = 'quizlet' AND lang = 'de';

