UPDATE tools SET faq = $x$[{"q": "Що таке Quizlet?", "a": "Quizlet — це навчальна платформа для студентів і вчителів. Вона перетворює ваші конспекти, документи та записані лекції на картки для запам'ятовування, навчальні посібники, практичні тести та ігри, а також пропонує адаптивний режим Learn, інтервальне повторення та експертні рішення підручників."}, {"q": "Чи Quizlet безкоштовний?", "a": "Так, Quizlet має безкоштовний план, і він безкоштовний для вчителів. Quizlet Plus додає 3 практичні тести, 3 питання-відповіді або рішення підручників і 20 раундів Learn на місяць без реклами, а Plus Unlimited знімає ці обмеження. Ціни залежать від країни й того, чи обрано щомісячну, чи річну оплату."}, {"q": "Які AI-функції має Quizlet?", "a": "Quizlet може пояснювати навчальний матеріал і генерувати на його основі практичні матеріали, перетворювати записані лекції на навчальні посібники й картки, конвертувати конспекти на розмовні подкасти та планувати повторення за допомогою інтервального повторення. Також є додаток усередині ChatGPT для створення наборів карток."}, {"q": "Чи має Quizlet Plus безкоштовний пробний період?", "a": "Так, річні плани Quizlet Plus включають 7-денний безкоштовний пробний період, після чого з вас стягнеться плата за рік, якщо ви не скасуєте підписку. Місячні плани не мають права на пробний період."}]$x$::jsonb
