UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Quizlet ?", "a": "Quizlet est une plateforme d'étude pour les étudiants et les enseignants. Elle transforme vos notes, documents et cours enregistrés en fiches de révision, guides d'étude, tests d'entraînement et jeux, et propose un mode Learn adaptatif, la répétition espacée et des solutions de manuels rédigées par des experts."}, {"q": "Quizlet est-il gratuit ?", "a": "Oui, Quizlet propose un plan gratuit, et il est gratuit pour les enseignants. Quizlet Plus ajoute 3 tests d'entraînement, 3 questions-réponses ou solutions de manuels et 20 sessions Learn par mois sans publicité, et Plus Unlimited supprime ces limites. Les tarifs varient selon le pays et selon que vous choisissez une facturation mensuelle ou annuelle."}, {"q": "Quelles fonctionnalités d'IA Quizlet propose-t-il ?", "a": "Quizlet peut expliquer le matériel d'étude et en générer des exercices d'entraînement, transformer des cours enregistrés en guides d'étude et fiches de révision, convertir des notes en podcasts conversationnels, et planifier des révisions avec la répétition espacée. Elle dispose aussi d'une application dans ChatGPT pour créer des ensembles de fiches de révision."}, {"q": "Quizlet Plus propose-t-il un essai gratuit ?", "a": "Oui, les formules annuelles Quizlet Plus incluent un essai gratuit de 7 jours, après quoi vous êtes facturé pour l'année sauf si vous annulez. Les formules mensuelles ne sont pas éligibles à l'essai."}]$x$::jsonb
