UPDATE tools SET faq = $x$[{"a": "Power BI — это инструмент бизнес-аналитики от Microsoft для подключения к данным, построения моделей данных и публикации интерактивных отчётов и дашбордов. Отчёты создаются в Power BI Desktop и предоставляются через сервис Power BI, Teams и мобильные приложения. Он входит в состав Microsoft Fabric.", "q": "Что такое Microsoft Power BI?"}, {"a": "Бесплатная учётная запись позволяет создавать отчёты для личного использования, но не допускает общий доступ или Copilot. Power BI Pro стоит $14 за пользователя в месяц при ежегодном выставлении счёта и входит в Microsoft 365 E5. Premium Per User стоит $24 за пользователя в месяц при ежегодном выставлении счёта. Ёмкость Fabric оценивается с оплатой по факту использования или по годовой резервации.", "q": "Сколько стоит Power BI?"}, {"a": "Нет. Для Copilot в Power BI требуется, чтобы отчёт или рабочая область находились на платной ёмкости Microsoft Fabric уровня F2 или выше либо Power BI Premium P1 или выше. Одной лицензии Pro или Premium Per User недостаточно, а пробные ёмкости не поддерживаются.", "q": "Включён ли Copilot в Power BI Pro?"}, {"a": "Copilot может отвечать на вопросы о ваших данных, составлять сводки отчётов, находить отчёты и модели, создавать и редактировать страницы отчётов, добавлять описательные визуальные элементы, писать запросы DAX и предлагать улучшения семантических моделей. Панель Copilot в отчётах общедоступна; автономный агент и некоторые другие возможности находятся в предварительной версии.", "q": "Что умеет делать Copilot в Power BI?"}]$x$::jsonb
 WHERE slug = 'power-bi' AND lang = 'ru';

UPDATE tools SET best_for = $x$Бізнес-дашборди та звіти з Copilot для запитань, підсумків і DAX$x$
