UPDATE tools SET faq = $x$[{"a": "Power BI é a ferramenta de business intelligence da Microsoft para se conectar a dados, criar modelos de dados e publicar relatórios e painéis interativos. Os relatórios são criados no Power BI Desktop e compartilhados pelo serviço Power BI, Teams e aplicativos móveis. Faz parte do Microsoft Fabric.", "q": "O que é o Microsoft Power BI?"}, {"a": "Uma conta gratuita permite criar relatórios para uso próprio, mas não permite compartilhamento nem Copilot. O Power BI Pro custa US$ 14 por usuário por mês, cobrado anualmente, e está incluído no Microsoft 365 E5. O Premium Per User custa US$ 24 por usuário por mês, cobrado anualmente. A capacidade do Fabric é precificada por consumo ou por reserva anual.", "q": "Quanto custa o Power BI?"}, {"a": "Não. O Copilot no Power BI requer que o relatório ou workspace esteja em uma capacidade paga do Microsoft Fabric de F2 ou superior ou Power BI Premium P1 ou superior. Apenas uma licença Pro ou Premium Per User não é suficiente, e capacidades de teste não são suportadas.", "q": "O Copilot está incluído no Power BI Pro?"}, {"a": "O Copilot pode responder perguntas sobre seus dados, resumir relatórios, encontrar relatórios e modelos, criar e editar páginas de relatório, adicionar visuais narrativos, escrever consultas DAX e sugerir melhorias em modelos semânticos. O painel do Copilot nos relatórios está disponível de forma geral; o agente independente e algumas outras experiências estão em pré-visualização.", "q": "O que o Copilot pode fazer no Power BI?"}]$x$::jsonb
