UPDATE tools SET faq = $x$[{"a": "Base44 est un outil de création d'applications IA appartenant à Wix. Vous décrivez l'application, le site web ou l'agent IA que vous souhaitez en langage naturel, et Base44 construit le frontend, le backend, la base de données, l'authentification et l'hébergement afin qu'il puisse être mis en ligne immédiatement.", "q": "Qu'est-ce que Base44 ?"}, {"a": "Oui. Le plan Free comprend 25 crédits de messages et 100 crédits d'intégration par mois ainsi que jusqu'à 5 applications. Les plans payants commencent avec Starter à 20 $ par mois en facturation mensuelle ou 16 $ par mois en facturation annuelle, et vont jusqu'à Elite à 200 $ par mois en facturation mensuelle ou 160 $ par mois en facturation annuelle.", "q": "Base44 est-il gratuit ?"}, {"a": "Wix a acquis Base44 en juin 2025. Base44 continue de fonctionner comme son propre produit, et en juin 2026, il a lancé Base 1, son propre modèle IA.", "q": "À qui appartient Base44 ?"}, {"a": "Base44 déclare que vous possédez tout ce que vous créez sur la plateforme. Les applications fonctionnent sur le backend et l'hébergement intégrés de Base44, et l'intégration GitHub est disponible à partir du plan Builder.", "q": "Est-ce que je possède les applications que je crée sur Base44 ?"}]$x$::jsonb
 WHERE slug = 'base44' AND lang = 'fr';

