UPDATE tools SET faq = $x$[{"a": "Base44 é um criador de aplicativos de IA de propriedade da Wix. Você descreve o aplicativo, site ou agente de IA que deseja em linguagem simples, e a Base44 constrói o frontend, o backend, o banco de dados, a autenticação e a hospedagem para que ele possa entrar no ar imediatamente.", "q": "O que é Base44?"}, {"a": "Sim. O plano Free inclui 25 créditos de mensagem e 100 créditos de integração por mês e até 5 aplicativos. Os planos pagos começam com o Starter a $20 por mês na cobrança mensal ou $16 por mês na cobrança anual, e vão até o Elite a $200 por mês na cobrança mensal ou $160 por mês na cobrança anual.", "q": "Base44 é gratuito?"}, {"a": "A Wix adquiriu a Base44 em junho de 2025. A Base44 continua operando como produto próprio, e em junho de 2026 lançou o Base 1, seu próprio modelo de IA.", "q": "Quem é dono da Base44?"}, {"a": "A Base44 afirma que você é dono de tudo o que constrói na plataforma. Os aplicativos rodam no backend e na hospedagem integrados da Base44, e a integração com GitHub está disponível a partir do plano Builder.", "q": "Eu sou dono dos aplicativos que crio na Base44?"}]$x$::jsonb
