 WHERE slug = 'freepik' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Is Freepik now called Magnific?", "a": "Yes. On April 28, 2026 Freepik rebranded as Magnific, uniting its stock library, AI generation tools and the Magnific upscaler under one name. freepik.com now redirects to magnific.com."}, {"q": "Is Magnific (Freepik) free?", "a": "There is a free plan with no credits but daily limits, such as up to 20 AI image generations and 10 stock downloads a day, for personal use with attribution. Paid plans (Premium, Premium+, Pro, Business) add monthly credits, premium stock and a commercial license; prices are shown in local currency and vary by region."}, {"q": "Which AI models does Magnific include?", "a": "Magnific offers many leading third-party models, including Kling, Seedance, Google Veo, Gemini Omni, MiniMax, Nano Banana, FLUX, Recraft, Ideogram and Grok, plus its own Magnific One image model and music and sound tools from Google Lyria and ElevenLabs."}, {"q": "What does unlimited mean on Magnific?", "a": "Premium+ and Pro include unlimited generation on most image models and some video models. Some premium models and all video, audio and editing tools still consume credits, and speed can be limited during busy periods."}]$x$::jsonb
