UPDATE tools SET faq = $x$[{"q": "A Freepik agora se chama Magnific?", "a": "Sim. Em 28 de abril de 2026, a Freepik se rebatizou como Magnific, unindo sua biblioteca de banco de imagens, ferramentas de geração por IA e o upscaler Magnific sob um único nome. O site freepik.com agora redireciona para magnific.com."}, {"q": "O Magnific (Freepik) é gratuito?", "a": "Existe um plano gratuito sem créditos, mas com limites diários, como até 20 gerações de imagem por IA e 10 downloads de banco de imagens por dia, para uso pessoal com atribuição. Os planos pagos (Premium, Premium+, Pro, Business) adicionam créditos mensais, banco de imagens premium e licença comercial; os preços são exibidos na moeda local e variam por região."}, {"q": "Quais modelos de IA o Magnific inclui?", "a": "O Magnific oferece muitos modelos líderes de terceiros, incluindo Kling, Seedance, Google Veo, Gemini Omni, MiniMax, Nano Banana, FLUX, Recraft, Ideogram e Grok, além de seu próprio modelo de imagem Magnific One e ferramentas de música e som do Google Lyria e ElevenLabs."}, {"q": "O que significa ilimitado no Magnific?", "a": "O Premium+ e o Pro incluem geração ilimitada na maioria dos modelos de imagem e em alguns modelos de vídeo. Alguns modelos premium e todas as ferramentas de vídeo, áudio e edição ainda consomem créditos, e a velocidade pode ser limitada em períodos de alta demanda."}]$x$::jsonb
 WHERE slug = 'freepik' AND lang = 'pt';
